using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
public partial class ActorPickerOperations:RefCounted
{
    private static GArray Definitions(PopupPanel owner)=>owner.Get("definitions").AsGodotArray();private static T Ui<T>(PopupPanel owner,string name) where T:GodotObject=>owner.Get(name).AsGodotObject() as T??throw new InvalidOperationException(name);private static string Searchable(Resource definition)=>(definition.Get("display_name").AsString()+" "+definition.Get("description").AsString()+" "+definition.Get("category").AsString()).ToLowerInvariant();
    public void setup(PopupPanel owner,GArray types)
    {
        owner.Set("definitions",types);owner.AddThemeStyleboxOverride("panel",box(new Color("101923"),new Color("496579"),13,2));var margin=new MarginContainer();foreach(string side in new[]{"left","right","top","bottom"})margin.AddThemeConstantOverride("margin_"+side,18);owner.AddChild(margin);var column=new VBoxContainer();column.AddThemeConstantOverride("separation",12);margin.AddChild(column);var header=new HBoxContainer();column.AddChild(header);var title=new Label{Text="Add an actor",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};title.AddThemeFontSizeOverride("font_size",24);header.AddChild(title);var close=new Button{Text="×",TooltipText="Close"};close.Pressed+=owner.Hide;header.AddChild(close);var location=new Label{Modulate=new Color("91b4c5")};owner.Set("location_label",location);column.AddChild(location);var search=new LineEdit{PlaceholderText="Search actors…",ClearButtonEnabled=true,CustomMinimumSize=new Vector2(0,38)};owner.Set("search",search);column.AddChild(search);search.TextChanged+=_=>rebuild(owner);search.TextSubmitted+=_=>{var matches=owner.Get("_matches").AsGodotArray();if(matches.Count>0)choose(owner,matches[0].AsInt32());};var navigation=new HBoxContainer();column.AddChild(navigation);var result=new Label{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};result.AddThemeColorOverride("font_color",new Color("829eb2"));owner.Set("result_label",result);navigation.AddChild(result);foreach(var entry in new[]{("Expand all",true),("Collapse all",false)}){var button=new Button{Text=entry.Item1,Flat=true};navigation.AddChild(button);button.Pressed+=()=>{var expanded=owner.Get("expanded").AsGodotDictionary();foreach(var value in Definitions(owner))expanded[value.As<Resource>().Get("category")]=entry.Item2;rebuild(owner);};}var scroll=new ScrollContainer{CustomMinimumSize=new Vector2(540,330),SizeFlagsVertical=Control.SizeFlags.ExpandFill};column.AddChild(scroll);var cards=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};cards.AddThemeConstantOverride("separation",8);owner.Set("cards",cards);scroll.AddChild(cards);rebuild(owner);
    }
    public void open(PopupPanel owner,int layer,double time){owner.Set("category","All");Ui<Label>(owner,"location_label").Text=$"LAYER {layer+1}    /    {time:F2} s";Ui<LineEdit>(owner,"search").Text="";rebuild(owner);owner.PopupCentered(new Vector2I(620,600));Ui<LineEdit>(owner,"search").GrabFocus();}
    public void rebuild(PopupPanel owner)
    {
        var cards=Ui<VBoxContainer>(owner,"cards");foreach(var child in cards.GetChildren()){cards.RemoveChild(child);child.QueueFree();}var matches=owner.Get("_matches").AsGodotArray();matches.Clear();var definitions=Definitions(owner);string category=owner.Get("category").AsString(),query=Ui<LineEdit>(owner,"search").Text.Trim().ToLowerInvariant();bool searching=Ui<LineEdit>(owner,"search").Text.Length>0;var candidates=Enumerable.Range(0,definitions.Count).Where(index=>{var item=definitions[index].As<Resource>();return (category=="All"||category==item.Get("category").AsString())&&(query.Length==0||Searchable(item).Contains(query,StringComparison.Ordinal));}).ToArray();var counts=candidates.GroupBy(index=>definitions[index].As<Resource>().Get("category").AsString()).ToDictionary(group=>group.Key,group=>group.Count());var groups=new Dictionary<string,VBoxContainer>();var expanded=owner.Get("expanded").AsGodotDictionary();foreach(int index in candidates){var definition=definitions[index].As<Resource>();string group=definition.Get("category").AsString();matches.Add(index);if(!groups.TryGetValue(group,out var body)){var section=new VBoxContainer();cards.AddChild(section);bool isExpanded=expanded.TryGetValue(group,out var expandedValue)?expandedValue.AsBool():group is "Shapes" or "Text";var header=new Button{Alignment=HorizontalAlignment.Left,ToggleMode=true,ButtonPressed=isExpanded||searching,CustomMinimumSize=new Vector2(0,38)};header.Text=(header.ButtonPressed?"▾  ":"▸  ")+category_symbol(group)+"  "+group+"    "+counts[group];header.AddThemeColorOverride("font_color",new Color("85d9c0"));section.AddChild(header);body=new VBoxContainer{Visible=header.ButtonPressed};body.AddThemeConstantOverride("separation",6);section.AddChild(body);groups[group]=body;var container=body;header.Toggled+=value=>{expanded[group]=value;container.Visible=value;header.Text=(value?"▾  ":"▸  ")+category_symbol(group)+"  "+group+"    "+category_count(owner,group);};}var card=new Button{Name="Actor_"+definition.Get("type_id").AsString(),Alignment=HorizontalAlignment.Left,CustomMinimumSize=new Vector2(0,58)};card.AddThemeFontSizeOverride("font_size",13);var accent=new Color(group switch{"Shapes"=>"85d9c0","Text"=>"bfa4ed","Media"=>"83cddd","Lighting"=>"efc47f","Utilities"=>"8fbcef","Video"=>"e48da8",_=>"aebfcc"});var style=new StyleBoxFlat{BgColor=new Color("253345"),BorderColor=accent,BorderWidthLeft=3};style.SetCornerRadiusAll(7);card.AddThemeStyleboxOverride("normal",style);var hover=(StyleBoxFlat)style.Duplicate();hover.BgColor=new Color("344c60");card.AddThemeStyleboxOverride("hover",hover);var icon=new TextureRect{Texture=definition.Get("icon").As<Texture2D>(),CustomMinimumSize=new Vector2(48,48),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered,MouseFilter=Control.MouseFilterEnum.Ignore};card.AddChild(icon);icon.Position=new Vector2(14,14);var title=new Label{Text=definition.Get("display_name").AsString()+"   /   "+group,Modulate=accent,MouseFilter=Control.MouseFilterEnum.Ignore};title.AddThemeFontSizeOverride("font_size",15);card.AddChild(title);title.Position=new Vector2(76,10);var description=new Label{Text=definition.Get("description").AsString(),Modulate=new Color("bdcddd"),MouseFilter=Control.MouseFilterEnum.Ignore,AutowrapMode=TextServer.AutowrapMode.WordSmart};description.AddThemeFontSizeOverride("font_size",12);card.AddChild(description);description.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);description.OffsetLeft=76;description.OffsetRight=-16;description.OffsetTop=34;description.OffsetBottom=-6;card.Pressed+=()=>choose(owner,index);body.AddChild(card);}if(matches.Count==0)cards.AddChild(new Label{Text="No matching actors. Try another search or category."});Ui<Label>(owner,"result_label").Text=$"{matches.Count} actor{(matches.Count==1?"":"s")}  •  Enter adds the first match";
    }
    public int category_count(PopupPanel owner,string category){var search=owner.Get("search").As<LineEdit>();string query=search?.Text.Trim().ToLowerInvariant()??"";return Definitions(owner).Count(value=>{var definition=value.As<Resource>();return definition.Get("category").AsString()==category&&(query.Length==0||Searchable(definition).Contains(query,StringComparison.Ordinal));});}
    public string category_symbol(string category)=>category switch{"Shapes"=>"◇","Text"=>"T","Media"=>"▣","Lighting"=>"☀","Utilities"=>"⌁","Video"=>"▶",_=>"•"};
    public StyleBoxFlat box(Color color,Color border,int radius,int width){var style=new StyleBoxFlat{BgColor=color,BorderColor=border};style.SetBorderWidthAll(width);style.SetCornerRadiusAll(radius);return style;}
    public void choose(PopupPanel owner,int index){owner.Hide();owner.EmitSignal("actor_chosen",index);}
}
